CREATE POLICY "Admins upload catalog images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'catalog-images' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins view catalog images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'catalog-images' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update catalog images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'catalog-images' AND private.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'catalog-images' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete catalog images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'catalog-images' AND private.has_role(auth.uid(), 'admin'));